function check(input, actual, expected) {
  const [operations, args] = input;
  if (!Array.isArray(actual) || actual.length !== operations.length) return false;
  const counts = new Map();
  for (let i = 0; i < operations.length; i++) {
    const op = operations[i], got = actual[i];
    if (op === 'getMaxKey' || op === 'getMinKey') {
      if (typeof got !== 'string') return false;
      if (counts.size === 0) { if (got !== '') return false; continue; }
      if (!counts.has(got)) return false;
      const values = [...counts.values()];
      const want = op === 'getMaxKey' ? Math.max(...values) : Math.min(...values);
      if (counts.get(got) !== want) return false;
      continue;
    }
    if (got !== null) return false;
    const key = args[i][0];
    if (op === 'inc') counts.set(key, (counts.get(key) || 0) + 1);
    if (op === 'dec') {
      const left = counts.get(key) - 1;
      if (left === 0) counts.delete(key); else counts.set(key, left);
    }
  }
  return true;
}

