function validate([operations, args]) {
  if (operations[0] !== 'AllOne') return 'Start with AllOne.';
  const counts = new Map();
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i];
    if (op === 'constructor' || op === 'AllOne') return 'AllOne can only be the first operation.';
    if (op !== 'inc' && op !== 'dec') continue;
    const key = args[i][0];
    if (!/^[a-z]{1,10}$/.test(key)) return 'Each key is 1 to 10 lowercase letters.';
    if (op === 'inc') counts.set(key, (counts.get(key) || 0) + 1);
    else {
      if (!counts.has(key)) return 'dec is only called with a key that is currently stored.';
      const left = counts.get(key) - 1;
      if (left === 0) counts.delete(key); else counts.set(key, left);
    }
  }
  return null;
}

