class AllOne {
  constructor() {
    this.head = { count: 0, keys: new Set(), prev: null, next: null };
    this.tail = { count: 0, keys: new Set(), prev: this.head, next: null };
    this.head.next = this.tail;
    this.bucketOf = new Map();
  }

  inc(key) {
    const current = this.bucketOf.get(key) || this.head;
    let target = current.next;
    if (target === this.tail || target.count !== current.count + 1) {
      target = this.insertAfter(current, current.count + 1);
    }
    target.keys.add(key);
    this.bucketOf.set(key, target);
    if (current !== this.head) {
      this.removeKey(current, key);
    }
  }

  dec(key) {
    const current = this.bucketOf.get(key);
    if (current.count === 1) {
      this.bucketOf.delete(key);
    } else {
      let target = current.prev;
      if (target === this.head || target.count !== current.count - 1) {
        target = this.insertAfter(current.prev, current.count - 1);
      }
      target.keys.add(key);
      this.bucketOf.set(key, target);
    }
    this.removeKey(current, key);
  }

  getMaxKey() {
    if (this.tail.prev === this.head) return '';
    return this.tail.prev.keys.values().next().value;
  }

  getMinKey() {
    if (this.head.next === this.tail) return '';
    return this.head.next.keys.values().next().value;
  }

  insertAfter(node, count) {
    const bucket = { count, keys: new Set(), prev: node, next: node.next };
    node.next.prev = bucket;
    node.next = bucket;
    return bucket;
  }

  removeKey(bucket, key) {
    bucket.keys.delete(key);
    if (bucket.keys.size === 0) {
      bucket.prev.next = bucket.next;
      bucket.next.prev = bucket.prev;
    }
  }
}

