  }
  dec(key) {
    this.counts.set(key, this.counts.get(key) - 1);
    if (this.counts.get(key) === 0) this.counts.delete(key);
  }
  getMaxKey() {
    let best = '';
    for (const [key, count] of this.counts) if (best === '' || count > this.counts.get(best)) best = key;
    return best;
  }
  getMinKey() {
    let best = '';
    for (const [key, count] of this.counts) if (best === '' || count < this.counts.get(best)) best = key;
    return best;
  }
}

