function generate(rand, size) {
  const word = () => { let s = ''; const n = 1 + Math.floor(rand() * 10); for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * 26)); return s; };
  const pool = size === 'large' ? Array.from({ length: 40 }, word) : ['a', 'b', 'c', 'hello', 'leet', 'zzzzzzzzzz'].slice(0, 2 + Math.floor(rand() * 4));
  const calls = size === 'large' ? 499 : 1 + Math.floor(rand() * 16);
  const incRate = 0.35 + rand() * 0.3;
  const operations = ['AllOne'], args = [[]], counts = new Map();
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    if (roll < 0.3) {
      operations.push(rand() < 0.5 ? 'getMaxKey' : 'getMinKey');
      args.push([]);
    } else if (counts.size === 0 || roll < 0.3 + incRate) {
      const key = pool[Math.floor(rand() * pool.length)];
      counts.set(key, (counts.get(key) || 0) + 1);
      operations.push('inc');
      args.push([key]);
    } else {
      const stored = [...counts.keys()];
      const key = stored[Math.floor(rand() * stored.length)];
      const left = counts.get(key) - 1;
      if (left === 0) counts.delete(key); else counts.set(key, left);
      operations.push('dec');
      args.push([key]);
    }
  }
  return [operations, args];
}
